import * as T from 'three';
export function createDoorSystem(scene,{canvas,onChange,getCamera,getMode}){
 const root=new T.Group();root.name='Original source door leaves';scene.add(root);const doors=[];let nearest=null;const $=s=>document.querySelector(s);
 function sync(){for(const d of doors){const row=$(`[data-door="${d.id}"]`);if(row){row.setAttribute('aria-pressed',String(d.open));row.innerHTML=`<span>${d.name}</span><span>${d.open?'Open':'Closed'}</span>`;}}$('#all-doors').textContent=doors.some(d=>!d.open)?'Open all doors':'Close all doors';canvas.dataset.doors=JSON.stringify(doors.map(d=>({id:d.id,open:d.open,rotation:+d.pivot.rotation.y.toFixed(3),sourceAngle:d.sourceAngle,slide:d.facade?d.pivot.position.toArray().map(v=>+v.toFixed(3)):undefined})));onChange();}
 function toggle(d,open=!d.open){d.open=open;sync();}
 async function load(loadModel,style){const response=await fetch('./assets/optimized/doors/manifest.json?v=sky-system-8-final');if(!response.ok)throw Error('Door definitions unavailable');const defs=(await response.json()).doors;for(const def of defs){const gltf=await loadModel(def.url+'?v=sky-system-8-final'),leaf=gltf.scene;style(leaf);root.updateMatrixWorld(true);root.add(leaf);root.updateMatrixWorld(true);const pivot=new T.Group();pivot.position.fromArray(def.hinge);root.add(pivot);pivot.attach(leaf);const d={...def,leaf,pivot,open:true,progress:1,center:new T.Box3().setFromObject(leaf,true).getCenter(new T.Vector3())};leaf.traverse(o=>{if(o.isMesh)o.userData.interactiveDoor=d.id;});doors.push(d);const button=document.createElement('button');button.className='door-row';button.dataset.door=d.id;button.onclick=()=>toggle(d);$('#door-list').append(button);}$('#door-count').textContent=doors.length;sync();return root;}
 function bindInterior(interior){
  const old=new Map(doors.filter(d=>d.facade).map(d=>[d.id,d.open]));for(let i=doors.length-1;i>=0;i--)if(doors[i].facade){$(`[data-door="${doors[i].id}"]`)?.remove();doors.splice(i,1);}
  interior.root.updateMatrixWorld(true);const leaves=[];interior.root.traverse(n=>{if(n.userData.facadeDoor)leaves.push(n);});
  for(const leaf of leaves){const def=leaf.userData.facadeDoor,id=leaf.userData.itemId,pivot=new T.Group();interior.root.add(pivot);interior.root.updateMatrixWorld(true);pivot.attach(leaf);const open=old.get(id)||false,d={id,name:def.name,leaf,pivot,facade:true,travel:def.travel,open,progress:open?1:0,center:new T.Box3().setFromObject(leaf,true).getCenter(new T.Vector3())};pivot.position.fromArray(d.travel).multiplyScalar(d.progress);leaf.traverse(o=>{if(o.isMesh)o.userData.interactiveDoor=id;});doors.push(d);const button=document.createElement('button');button.className='door-row';button.dataset.door=id;button.onclick=()=>toggle(d);$('#door-list').append(button);}
  $('#door-count').textContent=doors.length;sync();
 }
 function update(dt){let changed=false;for(const d of doors){const next=T.MathUtils.damp(d.progress,d.open?1:0,6,dt);if(Math.abs(next-d.progress)>.0001){d.progress=next;if(d.facade)d.pivot.position.fromArray(d.travel).multiplyScalar(next);else d.pivot.rotation.y=d.sourceAngle*(next-1);changed=true;}}nearest=null;if(getMode()==='walk'){let range=3;for(const d of doors){const distance=getCamera().position.distanceTo(d.center);if(distance<range){nearest=d;range=distance;}}}$('#door-action').hidden=!nearest;if(nearest)$('#door-action').innerHTML=(nearest.open?'Close':'Open')+' '+nearest.name+' <kbd>F</kbd>';if(changed)sync();return changed;}
 $('#all-doors').onclick=()=>{const open=doors.some(d=>!d.open);doors.forEach(d=>d.open=open);sync();};$('#door-action').onclick=()=>{if(nearest)toggle(nearest);};window.addEventListener('keydown',e=>{if(e.code==='KeyF'&&getMode()==='walk'&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)){if(nearest)toggle(nearest);e.preventDefault();}});
 let down;canvas.addEventListener('pointerdown',e=>down=[e.clientX,e.clientY]);canvas.addEventListener('click',e=>{if(getMode()!=='walk'||!down||Math.hypot(e.clientX-down[0],e.clientY-down[1])>6)return;const ray=new T.Raycaster();ray.setFromCamera(new T.Vector2(e.clientX/innerWidth*2-1,-e.clientY/innerHeight*2+1),getCamera());const hit=ray.intersectObjects(doors.map(d=>d.leaf),true).find(h=>h.distance<3.5&&h.object.userData.interactiveDoor);if(hit)toggle(doors.find(d=>d.id===hit.object.userData.interactiveDoor));});
 return{root,load,bindInterior,update,get doors(){return doors;}};
}
